    headers = None
    ncols = 0
    records = []
    for row in reader:
        if len(row) == 0:
            continue
        if len(row) == 1 and row[0].strip() == "":
            continue
        if headers is None:
            headers = row
            ncols = len(headers)
            if len(set(headers)) != len(headers):
                raise ValueError("duplicate headers")
            continue
        if len(row) != ncols:
            raise ValueError("field count mismatch")
        records.append(dict(zip(headers, row)))
    if headers is None:
        return []
    return records

def column_values(records, name):
    return [row[name] for row in records]
