{"files": {"core.py": "import bisect

def build_order(graph):
    dep_map = {}
    nodes = set(graph)
    for job, deps in graph.items():
        dset = set(deps)
        dep_map[job] = dset
        nodes.update(dset)
    indegree = {n: 0 for n in nodes}
    dependents = {n: set() for n in nodes}
    for job, dset in dep_map.items():
        for d in dset:
            indegree[job] += 1
            dependents[d].add(job)
    ready = sorted(n for n in nodes if indegree[n] == 0)
    result = []
    while ready:
        cur = ready.pop(0)
        result.append(cur)
        for nxt in dependents[cur]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                bisect.insort(ready, nxt)
    if len(result) != len(nodes):
        raise ValueError("cycle detected")
    return result

def job_count(graph):
    return len(set(graph).union(*(set(v) for v in graph.values())))
"}}

