{"files": {"core.py": "import heapq

def build_order(graph):
    deps = {}
    nodes = set(graph)
    for value in graph.values():
        for dep in value:
            nodes.add(dep)
    for node in nodes:
        if node in graph:
            deps[node] = set(graph[node])
        else:
            deps[node] = set()
    indegree = {node: len(deps[node]) for node in nodes}
    dependents = {node: set() for node in nodes}
    for node in nodes:
        for dep in deps[node]:
            dependents[dep].add(node)
    heap = sorted([node for node in nodes if indegree[node] == 0])
    heapq.heapify(heap)
    result = []
    while heap:
        job = heapq.heappop(heap)
        result.append(job)
        for dependent in dependents[job]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(heap, dependent)
    if len(result) != len(nodes):
        raise ValueError("cycle detected")
    return result

def job_count(graph):
    return len(set(graph).union(*(set(v) for v in graph.values())))
"}}

{"files": {"core.py": "from urllib.parse import quote_plus

def encode_query(pairs):
    parts = []
    for k, v in pairs:
        if v is None:
            continue
        parts.append(f"{quote_plus(str(k), safe='')}={quote_plus(str(v), safe='')}")
    return "&".join(parts)

