    visiting = set()

    def resolve_one(key):
        if key in resolved:
            return resolved[key]
        if key in visiting:
            raise ValueError(f"reference cycle involving '{key}'")
        visiting.add(key)
        raw = data[key]
        parts = []
        i = 0
        n = len(raw)
        while i < n:
