                    buf.append('$')
                    i += 2
                elif i + 1 < n and s[i + 1] == '{':
                    j = s.find('}', i + 2)
                    if j == -1:
                        raise ValueError(f'unclosed reference in {key!r}: {s!r}')
                    if buf:
                        tokens.append(('lit', ''.join(buf)))
                        buf = []
                    name = s[i + 2:j]
                    tokens.append(('ref', name))
                    i = j + 1
                else:
                    buf.append('$')
                    i += 1
            else:
                buf.append(c)
                i += 1
        if buf:
            tokens.append(('lit', ''.join(buf)))
        parsed[key] = tokens
    refs = {}
    for key, tokens in parsed.items():
        refs[key] = [v for t, v in tokens if t == 'ref']
    resolved = {}
    state = {}  # 1=visiting, 2=done
    for start in list(values.keys()):
        if state.get(start) == 2:
            continue
        if state.get(start) == 1:
            raise ValueError(f'reference cycle at {start!r}')
        state[start] = 1
        stack = [(start, 0)]
        while stack:
            node, idx = stack[-1]
            rlist = refs[node]
            if idx < len(rlist):
                stack[-1] = (node, idx + 1)
                ref = rlist[idx]
                if ref not in parsed:
                    raise ValueError(f'unknown reference {ref!r} in {node!r}')
                st = state.get(ref, 0)
                if st == 1:
                    raise ValueError(f'reference cycle involving {ref!r}')
                if st == 2:
