                state[ref] = 1
                stack.append((ref, 0))
            else:
                parts = []
                for typ, val in parsed[node]:
                    if typ == 'lit':
                        parts.append(val)
                    else:
                        parts.append(resolved[val])
                resolved[node] = ''.join(parts)
                state[node] = 2
                stack.pop()
