{"files": {"core.py": "from copy import deepcopy

def encode_runs(values):
    result = []
    started = False
    cur_val = None
    cur_count = 0
    for v in values:
        if not started:
            cur_val = deepcopy(v)
            cur_count = 1
            started = True
        elif v == cur_val:
            cur_count += 1
        else:
            result.append((cur_val, cur_count))
            cur_val = deepcopy(v)
            cur_count = 1
    if started:
        result.append((cur_val, cur_count))
    return result

def decode_runs(runs):
    out = []
    for item in runs:
        try:
            value, count = item
        except (TypeError, ValueError):
            raise ValueError(f"invalid run: {item!r}")
        if isinstance(count, bool) or not isinstance(count, int):
            raise ValueError(f"invalid count: {count!r}")
        if count <= 0:
            raise ValueError(f"invalid count: {count!r}")
        for _ in range(count):
            out.append(deepcopy(value))
    return out

def encoded_size(runs): return len(runs)
"}}

