def read_records(text):
    if text is None:
        return []
    if isinstance(text, str) and text.strip() == "":
        return []
    f = io.StringIO(text)
    reader = csv.reader(f, delimiter=',', quotechar='"', doublequote=True, skipinitialspace=False)
    headers = None
    result = []
    for row in reader:
        if len(row) == 0:
            continue
        if len(row) == 1 and row[0] != "" and row[0].strip() == "":
            continue
        if headers is None:
            headers = row
            if len(set(headers)) != len(headers):
