{"files": {"core.py": "def resolve_config(values):
    resolved = {}
    visiting = set()

    def dfs(key):
        if key in resolved:
            return resolved[key]
        if key in visiting:
            raise ValueError(f"cycle detected at {key!r}")
        visiting.add(key)
        try:
            raw = values[key]
            parts = []
            i = 0
            n = len(raw)
            while i < n:
                c = raw[i]
                if c != '$':
                    parts.append(c)
                    i += 1
                    continue
                if i + 1 >= n:
                    parts.append('$')
                    i += 1
                elif raw[i + 1] == '$':
                    parts.append('$')
                    i += 2
                elif raw[i + 1] == '{':
                    j = raw.find('}', i + 2)
                    if j == -1:
                        raise ValueError(f"unclosed reference in {key!r}")
                    name = raw[i + 2:j]
                    if name not in values:
                        raise ValueError(f"unknown reference {name!r}")
                    parts.append(dfs(name))
                    i = j + 1
