    token_map = {}
    dep_map = {}
    for k in keys:
        raw = values[k]
        tokens = []
        buf = []
        i = 0
        n = len(raw)
        while i < n:
            c = raw[i]
            if c == '$':
                if i + 1 < n and raw[i + 1] == '$':
                    buf.append('$')
                    i += 2
                elif i + 1 < n and raw[i + 1] == '{':
                    j = raw.find('}', i + 2)
                    if j == -1:
                        raise ValueError(f"unclosed reference in key {k!r}")
                    if buf:
                        tokens.append(('lit', ''.join(buf)))
                        buf = []
                    name = raw[i + 2:j]
                    tokens.append(('ref', name))
                    i = j + 1
                else:
                    buf.append('$')
                    i += 1
            else:
                buf.append(c)
                i += 1
        if buf:
            tokens.append(('lit', ''.join(buf)))
        token_map[k] = tokens
        dep_map[k] = [v for t, v in tokens if t == 'ref']
    # Unknown references
    for k in keys:
        for name in dep_map[k]:
            if name not in values:
                raise ValueError(f"unknown reference {name!r} in key {k!r}")
    # Cycle detection + topological order (iterative DFS)
    color = {k: 0 for k in keys}  # 0=unvisited, 1=visiting, 2=done
    order = []
    for start in keys:
        if color[start] != 0:
            continue
        color[start] = 1
        stack_nodes = [start]
        stack_iters = [iter(dep_map[start])]
        while stack_nodes:
            try:
                nb = next(stack_iters[-1])
                st = color.get(nb, 0)
                if st == 1:
                    raise ValueError(f"reference cycle involving {nb!r}")
                elif st == 0:
                    color[nb] = 1
                    stack_nodes.append(nb)
                    stack_iters.append(iter(dep_map[nb]))
            except StopIteration:
                node = stack_nodes.pop()
                stack_iters.pop()
                color[node] = 2
                order.append(node)
    # Expand in dependency-first order; inserted values not rescanned
    resolved = {}
    for node in order:
        parts = []
        for typ, val in token_map[node]:
            if typ == 'lit':
                parts.append(val)
            else:
                parts.append(resolved[val])
        resolved[node] = ''.join(parts)
