    raw = {k: values[k] for k in values}
    deps = {}
    for k, v in raw.items():
        refs = []
        i = 0
        n = len(v)
        while i < n:
            c = v[i]
            if c == '$':
                if i + 1 < n and v[i + 1] == '$':
                    i += 2
                    continue
                elif i + 1 < n and v[i + 1] == '{':
                    j = v.find('}', i + 2)
                    if j == -1:
                        raise ValueError(f"unclosed reference in key {k!r}")
                    refs.append(v[i + 2:j])
                    i = j + 1
                    continue
                else:
                    i += 1
                    continue
            else:
                i += 1
        deps[k] = refs
    for k, refs in deps.items():
        for name in refs:
            if name not in raw:
                raise ValueError(f"unknown reference {name!r}")
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {k: WHITE for k in raw}
    order = []
    for start in raw:
        if color[start] != WHITE:
            continue
        color[start] = GRAY
        stack = [(start, 0)]
        while stack:
            node, idx = stack[-1]
            if idx < len(deps[node]):
                nxt = deps[node][idx]
                stack[-1] = (node, idx + 1)
                if color[nxt] == GRAY:
                    raise ValueError("reference cycle detected")
                elif color[nxt] == WHITE:
                    color[nxt] = GRAY
                    stack.append((nxt, 0))
            else:
                color[node] = BLACK
                order.append(node)
                stack.pop()
    resolved = {}
    for key in order:
        s = raw[key]
        parts = []
        i = 0
        n = len(s)
        while i < n:
            if s[i] == '$':
                if i + 1 < n and s[i + 1] == '$':
                    parts.append('$')
                    i += 2
                elif i + 1 < n and s[i + 1] == '{':
                    j = s.find('}', i + 2)
                    if j == -1:
                        raise ValueError(f"unclosed reference in key {key!r}")
                    name = s[i + 2:j]
                    if name not in resolved:
                        raise ValueError(f"unknown reference {name!r}")
                    parts.append(resolved[name])
                    i = j + 1
                else:
                    parts.append('$')
                    i += 1
            else:
                parts.append(s[i])
                i += 1
