{"files": {"core.py": "def resolve_config(values):
    parsed = {}
    refs_list = {}
    for key, raw in values.items():
        s = raw
        parts = []
        lit_buf = []
        def flush():
            if lit_buf:
                parts.append(('lit', ''.join(lit_buf)))
                lit_buf.clear()
        refs = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c == '$':
                if i + 1 < n and s[i + 1] == '$':
                    lit_buf.append('$')
                    i += 2
                elif i + 1 < n and s[i + 1] == '{':
                    j = s.find('}', i + 2)
                    if j == -1:
                        raise ValueError(f'unclosed reference in {key!r}')
                    name = s[i + 2:j]
                    flush()
                    parts.append(('ref', name))
                    refs.append(name)
                    i = j + 1
                else:
                    lit_buf.append('$')
                    i += 1
            else:
                lit_buf.append(c)
                i += 1
        flush()
        parsed[key] = parts
        refs_list[key] = refs
    for key, refs in refs_list.items():
        for name in refs:
            if name not in values:
                raise ValueError(f'unknown reference {name!r}')
    state = {}
    resolved = {}
    for start in values:
        if state.get(start, 0) != 0:
            continue
        state[start] = 1
        stack = [start]
        idx_stack = [0]
        while stack:
            node = stack[-1]
            refs = refs_list[node]
            i = idx_stack[-1]
            pushed = False
            while i < len(refs):
                dep = refs[i]
                st = state.get(dep, 0)
                if st == 1:
                    raise ValueError('reference cycle')
                elif st == 0:
                    idx_stack[-1] = i + 1
                    state[dep] = 1
                    stack.append(dep)
                    idx_stack.append(0)
                    pushed = True
                    break
                else:
                    i += 1
            if pushed:
                continue
            buf = []
            for typ, val in parsed[node]:
                if typ == 'lit':
                    buf.append(val)
                else:
                    buf.append(resolved[val])
            resolved[node] = ''.join(buf)
            state[node] = 2
            stack.pop()
            idx_stack.pop()
    return dict(resolved)

