import math

@dataclass
class Settings:
    timeout: float = 30.0
    retries: int = 3

def validate_timeout(value):
    if isinstance(value, bool):
        raise ValueError('invalid timeout')
    if isinstance(value, (int, float)):
        timeout = float(value)
    elif isinstance(value, str):
        try:
            timeout = float(value.strip() if value.strip() != '' else value)
        except (ValueError, AttributeError):
            raise ValueError('invalid timeout')
    else:
        raise ValueError('invalid timeout')
    if not math.isfinite(timeout) or timeout <= 0:
        raise ValueError('invalid timeout')
    return timeout

def load_settings(mapping):
    if mapping is None:
        mapping = {}
    if 'timeout' not in mapping:
        return Settings()
    return Settings(timeout=validate_timeout(mapping['timeout']))

def describe(settings):
    return f'timeout={settings.timeout:g}; retries={settings.retries}'
