    def __init__(self):
        self._counts = {}

    def add(self, word):
        self._counts[word] = self._counts.get(word, 0) + 1

    def remove(self, word):
        if word not in self._counts:
            return False
        if self._counts[word] <= 1:
            del self._counts[word]
        else:
            self._counts[word] -= 1
        return True

    def suggest(self, prefix, limit=5):
        if limit < 0:
            raise ValueError('limit must be non-negative')
        if limit == 0:
            return []
        matched = [w for w in self._counts if w.startswith(prefix)]
        matched.sort(key=lambda w: (-self._counts[w], w))
        return list(matched[:limit])

def highlight(word, prefix):
    return '[' + word[:len(prefix)] + ']' + word[len(prefix):]
